// GEOMETRY BEGIN — art.py reads this same geometry so wood and contacts coincide.
const STUMP = {left:88,right:168,top:168,bottom:208};
const SHAPE = [[0,14],[3,4],[3,-3],[2,-3],[2,-12],[-2,-12],[-2,-3],[-3,-3],[-3,4]];
// GEOMETRY END
const TUNE = {chargeMax:60,gravity:0.28,substeps:4,speedMin:5.6,speedRange:2,spinMin:0.14,spinRange:0.10,tolerance:24*Math.PI/180,perfect:6*Math.PI/180,flightLimit:180,feedback:45,rounds:10};
// Measured by real charge/release throws; the physics sweep guards these helper bands.
const RELEASE_ZONES = [{from:3,to:10,flips:1},{from:55,to:59,flips:2}];
function releaseZone(held){return RELEASE_ZONES.find(z=>held>=z.from&&held<=z.to);}
const TAU = Math.PI*2;
const SFX = {move:0,select:1,back:2,pause:3,launch:4,stick:5,miss:6,handoff:7,finish:8};
const SONG = {title:0,play:1}, SFX_CH = [6,7];
let fxNext=0,playing=-1;
function fx(n){sfx(n,SFX_CH[fxNext]);fxNext^=1;}
function play(n){if(playing!==n){playing=n;music(n);}}
let skipTitle=false,state='title',timer=0,clock=0,active=0,selection=0;
let players=[],knife=null,charge=0,neutral=false,resumeState='aim',resumeTimer=0,helpFrom='title',confirmAction='';
let last=null,particles=[],attemptLog=[];
let inputMask=0,prevMask=0;
const BUTTONS=[UP,DOWN,LEFT,RIGHT,A,B,START,SELECT];
const pressed=b=>!!(inputMask&(1<<b))&&!(prevMask&(1<<b));
function enter(s){state=s;timer=0;selection=0;}
function newKnife(){return{x:128,y:154,vx:0,vy:0,angle:0,omega:0,travel:0,armed:false,spent:false,age:0};}
function startGame(){
  players=Array.from({length:2},()=>({score:0,combo:0,bestCombo:0,hits:0,attempts:0}));
  active=0;charge=0;neutral=false;last=null;particles=[];attemptLog=[];knife=newKnife();enter('ready');play(SONG.play);
}
function init(){
  for(const [layer,key]of [[2,'far'],[1,'forest'],[0,'stump']]){
    const s=ART.scenes[key];bg(layer,{mx:s.mx,my:s.my,mw:s.w,mh:s.h,x:0,y:0,wrap:false,show:true});
  }
  blend({layers:['overlay'],half:true});brightness(15);
  startGame();if(!skipTitle){enter('title');play(SONG.title);}
}
function vertices(k){const c=Math.cos(k.angle),s=Math.sin(k.angle);return SHAPE.map(([x,y])=>({x:k.x+x*c+y*s,y:k.y-x*s+y*c}));}
function angleError(a){const n=((a%TAU)+TAU)%TAU;return Math.min(n,TAU-n);}
function launch(){
  const q=charge/TUNE.chargeMax;knife=newKnife();knife.vy=-(TUNE.speedMin+TUNE.speedRange*q);knife.omega=TUNE.spinMin+TUNE.spinRange*q;
  knife.held=charge;fx(SFX.launch);enter('flight');
}
// Earliest swept contact among actual outline vertices; index 0 is the pointed tip.
function contact(before,after){
  let first=null;
  const add=(time,index,side)=>{if(time>=0&&time<=1&&(!first||time<first.time-1e-8)){first={time,index,side};}};
  for(let i=0;i<after.length;i++){
    const a=before[i],b=after[i];
    if(a.y<STUMP.top&&b.y>=STUMP.top){const u=(STUMP.top-a.y)/(b.y-a.y),x=a.x+(b.x-a.x)*u;if(x>=STUMP.left&&x<=STUMP.right)add(u,i,'top');}
    for(const [edge,side]of [[STUMP.left,'left'],[STUMP.right,'right']]){
      if((side==='left'&&a.x<edge&&b.x>=edge)||(side==='right'&&a.x>edge&&b.x<=edge)){
        const u=(edge-a.x)/(b.x-a.x),y=a.y+(b.y-a.y)*u;if(y>=STUMP.top&&y<=STUMP.bottom)add(u,i,side);
      }
    }
  }
  return first;
}
function burst(x,y,good){for(let i=0;i<8&&particles.length<12;i++)particles.push({x,y,vx:rnd(2.2)-1.1,vy:-rnd(1.8)-0.2,life:30+rndi(0,14),good});}
function resolve(good,flips=0,error=0,reason=''){
  if(knife.spent)return;knife.spent=true;
  const p=players[active];p.attempts++;
  if(good){p.score+=10;p.combo++;p.bestCombo=Math.max(p.bestCombo,p.combo);p.hits++;knife.angle=0;knife.y=STUMP.top+1-14;knife.vy=0;knife.vx=0;knife.omega=0;fx(SFX.stick);}
  else {p.combo=0;knife.vy=-1.7;knife.vx=1.1;knife.omega=0.18;fx(SFX.miss);}
  last={good,flips,error,reason,points:good?10:0,player:active,held:knife.held};
  attemptLog.push({...last});burst(128,STUMP.top,good);enter('feedback');
}
function stepFlight(){
  const dt=1/TUNE.substeps;
  for(let j=0;j<TUNE.substeps&&state==='flight';j++){
    const old={...knife},before=vertices(knife);
    knife.vy+=TUNE.gravity*dt;knife.x+=knife.vx*dt;knife.y+=knife.vy*dt;knife.angle+=knife.omega*dt;knife.travel+=Math.abs(knife.omega*dt);
    const after=vertices(knife);
    if(!knife.armed&&Math.max(...after.map(v=>v.y))<STUMP.top-0.25)knife.armed=true;
    if(knife.armed){
      const hit=contact(before,after);
      if(hit){
        const angle=old.angle+(knife.angle-old.angle)*hit.time,error=angleError(angle);
        const traveled=old.travel+(knife.travel-old.travel)*hit.time;
        const flips=Math.floor((traveled+TUNE.tolerance+1e-8)/TAU);
        const good=hit.side==='top'&&hit.index===0&&knife.vy>0&&error<=TUNE.tolerance&&flips>=1;
        knife.x=old.x+(knife.x-old.x)*hit.time;knife.y=old.y+(knife.y-old.y)*hit.time;knife.angle=angle;
        resolve(good,good?flips:0,error,hit.index===0?'angle':'handle/side');return;
      }
    }
  }
  if(++knife.age>=TUNE.flightLimit||knife.y>224||knife.x< -32||knife.x>288)resolve(false,0,0,'out');
}
function nextTurn(){
  if(players.every(p=>p.attempts>=TUNE.rounds)){enter('results');fx(SFX.finish);return;}
  active^=1;knife=newKnife();charge=0;neutral=false;enter('ready');fx(SFX.handoff);
}
function pause(){resumeState=state==='charge'?'aim':state;resumeTimer=state==='charge'?0:timer;if(state==='charge'){charge=0;neutral=false;}enter('pause');fx(SFX.pause);}
function resume(){state=resumeState;timer=resumeTimer;neutral=false;}
function menuMove(n){if(pressed(UP)){selection=(selection+n-1)%n;fx(SFX.move);}if(pressed(DOWN)){selection=(selection+1)%n;fx(SFX.move);}}
function update(){
  inputMask=0;for(const b of BUTTONS)if(btn(b,0))inputMask|=1<<b;clock++;
  if(!['pause','help','confirm'].includes(state)&&!pressed(START))timer++;
  if(['aim','charge','flight','feedback'].includes(state)&&pressed(START))pause();
  else if(['aim','charge','ready'].includes(state)&&pressed(SELECT)){
    helpFrom=state==='charge'?'aim':state;charge=0;neutral=false;enter('help');
  }else if(state==='title'){
    menuMove(2);if(pressed(A)||pressed(START)){fx(SFX.select);if(selection===0)startGame();else{helpFrom='title';enter('help');}}
  }else if(state==='ready'){
    if(pressed(A)||pressed(START)){enter('aim');neutral=false;fx(SFX.select);}
  }else if(state==='aim'){
    if(!neutral){if(!btn(A)&&!btn(B))neutral=true;}
    else if(pressed(A)){charge=1;enter('charge');}
  }else if(state==='charge'){
    if(pressed(B)){charge=0;neutral=false;enter('aim');fx(SFX.back);}
    else if(!btn(A))launch();else charge=Math.min(TUNE.chargeMax,charge+1);
  }else if(state==='flight')stepFlight();
  else if(state==='feedback'){
    if(!last.good){knife.vy+=0.15;knife.y=Math.min(224,knife.y+knife.vy);knife.x+=knife.vx;knife.angle+=knife.omega;}
    if(timer>=TUNE.feedback||(timer>=15&&pressed(B)))nextTurn();
  }else if(state==='results'){
    menuMove(2);if(pressed(A)||pressed(START)){if(selection===0)startGame();else{enter('title');play(SONG.title);}}
  }else if(state==='pause'){
    menuMove(3);
    if(pressed(B)||pressed(START)){resume();fx(SFX.pause);}
    else if(pressed(A)){if(selection===0)resume();else{confirmAction=selection===1?'restart':'quit';enter('confirm');}}
  }else if(state==='confirm'){
    menuMove(2);if(pressed(B)){enter('pause');}
    else if(pressed(A)){if(selection===0)enter('pause');else if(confirmAction==='restart')startGame();else{enter('title');play(SONG.title);}}
  }else if(state==='help'){
    if(pressed(A)||pressed(B)||pressed(START)||pressed(SELECT)){enter(helpFrom);neutral=false;fx(SFX.back);}
  }
  if(!['pause','help','confirm'].includes(state)){
    for(const p of particles){p.life--;p.x+=p.vx;p.y+=p.vy;p.vy+=0.06;}particles=particles.filter(p=>p.life>0);
  }
  prevMask=inputMask;
}
function sprite(name,x,y,opts={}){const s=ART.sprites[name];spr(s.tile,Math.round(x),Math.round(y),{size:s.size,pal:s.pal,prio:3,...opts});}
function text(s,x,y,c=ART.colors.INK){print(s,x,y,c);}
function center(s,y,c=ART.colors.INK){text(s,128-s.length*4,y,c);}
function panel(x,y,w,h){rectfill(x+2,y+3,w,h,ART.colors.SHADOW);rectfill(x,y,w,h,ART.colors.PAPER);rect(x,y,w,h,ART.colors.BORDER);rect(x+2,y+2,w-4,h-4,ART.colors.CREAM);}
function drawMenu(items,x,y){items.forEach((s,i)=>text((i===selection?'> ':'  ')+s,x,y+i*16,i===selection?ART.colors.TEAL:ART.colors.INK));}
function drawKnife(){
  const pose=((Math.round(knife.angle/TAU*32)%32)+32)%32,k=pose%16,flip=pose>=16;
  sprite('knife'+k,knife.x-16+(flip?1:0),knife.y-16+(flip?1:0),{pal:active,fx:flip,fy:flip});
}
function drawPowerHelper(){
  const held=state==='charge'?charge:0,good=releaseZone(held);
  rectfill(0,192,256,32,ART.colors.CREAM);line(0,192,255,192,ART.colors.BORDER);
  text('1 FLIP',8,195,ART.colors.TEAL);text('2 FLIPS',192,195,ART.colors.TEAL);
  center(good?'RELEASE!':held===TUNE.chargeMax?'TOO MUCH':held?'CHARGING':'HOLD X',195,good?ART.colors.TEAL:ART.colors.INK);
  rectfill(6,205,244,16,ART.colors.BORDER);rectfill(8,207,240,12,ART.colors.INK);
  rectfill(8,207,held*4,12,active?ART.colors.ORANGE:ART.colors.TEAL);
  for(const z of RELEASE_ZONES)rectfill(8+(z.from-1)*4,207,(z.to-z.from+1)*4,12,ART.colors.GREEN);
  const x=held?8+(held-1)*4+1:8;
  rectfill(x-1,206,4,14,ART.colors.INK);rectfill(x,206,2,14,ART.colors.CREAM);
}
function draw(){
  cls();
  for(let i=0;i<5;i++){const x=(i*53+Math.floor(clock/(4+i)))%270-8,y=48+((i*37+Math.floor(clock/(14+i)))%88);sprite('leaf',x,y);}
  if(knife)drawKnife();
  for(const p of particles)sprite(p.good?'spark':'chip',p.x,p.y);
  rectfill(0,0,256,32,ART.colors.CREAM);line(0,31,255,31,ART.colors.BORDER);
  for(let i=0;i<2;i++){const x=i?176:8,p=players[i],c=i===active?ART.colors.TEAL:ART.colors.MUTED;
    text((i===active?'>':' ')+'P'+(i+1)+' '+String(p.score).padStart(3,'0'),x,5,c);
    text('STREAK '+p.combo,x,17,c);
  }
  center('ROUND',4,ART.colors.MUTED);center(Math.min(10,Math.floor(attemptLog.length/2)+1)+'/10',17);
  if(state==='aim'||state==='charge')drawPowerHelper();
  else{rectfill(0,208,256,16,ART.colors.CREAM);line(0,208,255,208,ART.colors.BORDER);text('HOLD X: charge  Z: cancel',8,213,ART.colors.MUTED);}
  if(state==='title'){
    panel(24,45,208,94);center('DUEL AT',57,ART.colors.TEAL);center('THE STUMP',73);center('A TWO-PLAYER FLIP DUEL',94,ART.colors.MUTED);drawMenu(['PLAY DUEL','HOW TO PLAY'],56,111);
    center('SHARE A KEYBOARD OR GAMEPAD',193,ART.colors.CREAM);
  }else if(state==='ready'){
    panel(32,62,192,65);center('PLAYER '+(active+1)+' - YOUR TURN',74,active?ART.colors.ORANGE:ART.colors.TEAL);center('X / ENTER: READY',94);center('Then hold X and release.',110,ART.colors.MUTED);
  }else if(state==='aim'){
    center('PLAYER '+(active+1)+': HOLD X TO CHARGE',43,ART.colors.CREAM);
  }else if(state==='feedback'){
    const label=last.good?(last.flips>1?'DOUBLE FLIP!':last.error<=TUNE.perfect?'PERFECT!':'STUCK!'):'MISS';
    center(label,56,last.good?ART.colors.CREAM:ART.colors.CREAM);center(last.good?'+10 POINTS':'TRY A DIFFERENT POWER',71,ART.colors.CREAM);
  }else if(state==='results'){
    panel(24,52,208,119);const a=players[0].score,b=players[1].score;
    center(a===b?'DRAW!':'PLAYER '+(a>b?1:2)+' WINS!',65,ART.colors.TEAL);
    center('P1 '+a+'    P2 '+b,87);center('10 THROWS EACH',103,ART.colors.MUTED);drawMenu(['REMATCH','TITLE'],64,125);
  }else if(state==='pause'){
    panel(32,64,192,96);center('PAUSED',76);drawMenu(['RESUME','RESTART DUEL','QUIT TO TITLE'],48,98);
  }else if(state==='confirm'){
    panel(16,64,224,92);center(confirmAction==='restart'?'RESTART THE DUEL?':'QUIT THIS DUEL?',76);center('Current points will be lost.',94,ART.colors.MUTED);drawMenu(['KEEP PLAYING','YES'],32,114);
  }else if(state==='help'){
    panel(8,36,240,168);center('HOW TO PLAY',47,ART.colors.TEAL);
    ['X: ready, then release.','Hold X to build power.','Release in the green zones.','Left: 1 flip. Right: 2 flips.','Tip-first landings: 10 pts.','Alternate after every throw.','Each player keeps a streak.','Z cancels before a throw.','Enter pauses. 10 throws each.','No saved records yet.'].forEach((s,i)=>text(s,16,63+i*12));
    center('X / Z: BACK',190,ART.colors.TEAL);
  }
}
function scanline(y){gradientLine(ART.gradients.sky,y);}
